contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: caller provides an amount and a hash; we then check
    // that lockInGuess always transfers exactly 1 ether from this contract caller
    // to contract c by observing address(c).balance change and that the guess slot is set.
    function runTest(bytes32 hash, uint256 sendAmount) public payable {
        // ensure the test caller has provided the ETH to forward
        require(address(this).balance >= sendAmount);
        // record balance before
        uint256 before = address(c).balance;

        // call lockInGuess forwarding sendAmount
        c.lockInGuess{value: sendAmount}(hash);

        // observe after balance
        uint256 after = address(c).balance;

        // The original contract requires exactly 1 ether be sent to lockInGuess,
        // so when lockInGuess succeeds it must have increased c.balance by exactly 1 ether
        // (i.e., after - before == 1 ether). The mutant removes that require and
        // therefore allows other sendAmount values that change balance by != 1 ether.
        assert(after - before == 1 ether);
    }

    // Allow this test contract to receive ETH so it can forward it in tests
    receive() external payable {}
}

