        try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        // In the original contract, lockInGuess only succeeds when msg.value == 1 ether.
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

