pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz parameter: amount sent when calling lockInGuess (can be any uint256)
    function testFuzz_property(uint256 payAmount) public {
        // keep the domain wide but reasonable (can't send more than available)
        payAmount = bound(payAmount, 0, 5 ether);

        // actor who will call lockInGuess
        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);

        bytes32 someGuess = keccak256(abi.encodePacked("guess"));

        // perform the call as the actor, sending payAmount wei
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: payAmount}(someGuess) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: in the REFERENCE contract, lockInGuess only succeeds
        // (i.e., does not revert) and records the guess (guesses[msg.sender].block != 0) when
        // and only when the caller sent exactly 1 ether. We can observe recording by checking
        // the auto-generated getter for guesses (struct members are accessible via the mapping getter):
        // c.guesses(addr) returns (uint256 block, bytes32 guess)

        (uint256 recordedBlock, bytes32 recordedGuess) = c.guesses(actor);

        // Single assertion: if payAmount == 1 ether then the call must have succeeded and the mapping
        // entry must be set (recordedBlock != 0 and recordedGuess == someGuess). For other payAmount
        // values the reference reverts and does not set the mapping; the mutant (which removed the
        // require) will allow non-1-ether payments to succeed and set the mapping, so the assertion
        // distinguishes reference (always holds) from mutant (fails for some inputs).
        if (payAmount == 1 ether) {
            assertTrue(ok && recordedBlock != 0 && recordedGuess == someGuess);
        } else {
            // For non-1-ether payments the reference will revert, so ok should be false and mapping unset
            assertTrue(!ok && recordedBlock == 0 && recordedGuess == bytes32(0));
        }
    }
}

