pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // deploy reference contract (the test runner will run this test against both reference and mutant builds)
        c = new C{value: 1 ether}();
    }

    // fuzzed params: an address actor and a bytes32 guessHash
    function testFuzz_property(address actor, bytes32 guessHash) public {
        // admissible actor: non-zero address and not this contract
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so they can send 1 ether
        vm.deal(actor, 2 ether);

        // perform the call as actor, sending exactly 1 ether as the contract requires
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // After a successful lockInGuess in the reference, the stored block should be strictly greater
        // than the block number at the time of call completion. We observe this by reading the public
        // autogenerated getter for the mapping (guesses) struct field `.block` via the contract's
        // external interface: c.guesses(actor).block. The test asserts that this relation holds.
        // This is a single assertion over c's public surface as required.
        (uint storedBlock, ) = _readGuessBlockAndDummy(actor);
        assertTrue(storedBlock > block.number);
    }

    // helper to access the mapping getter that returns the struct; the getter has the struct fields in order
    function _readGuessBlockAndDummy(address who) internal returns (uint, bytes32) {
        // The mapping getter for guesses returns (uint, bytes32) in the order declared in the struct
        // However solidity autogenerated getter names the function `guesses`, so call it directly.
        // Note: We call via low-level staticcall to avoid solidity compile-time typing problems if the
        // mapping getter signature is not directly accessible; but since C declares the struct as in spec,
        // we can call it as external view. To keep things simple and comply with the constraint "observe c
        // only via its public surface", we perform a normal call using abi.decode on the returned data.
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("guesses(address)", who));
        require(ok, "getter call failed");
        // struct: uint block; bytes32 guess;
        (uint blk, bytes32 g) = abi.decode(data, (uint, bytes32));
        return (blk, g);
    }
}

