pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: caller address and an arbitrary bytes32 guess
    function testFuzz_property(address caller, bytes32 guess) public {
        // keep caller a non-zero address and distinct from this test contract
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // fund the caller so it can send 1 ether
        vm.deal(caller, 1 ether);

        // Caller attempts to lock in a guess with exactly 1 ether
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        // Read stored guess.block via the auto-generated getter for the public mapping
        // The Guess struct fields are not public individually; we observe by calling settle behaviour
        // We rely on the reference guaranteeing the stored block is not equal to the current block.
        // To observe stored block we attempt to call settle now; in the reference this will revert
        // because it requires block.number > guesses[caller].block (stored is current+1), whereas
        // in the mutant (stored == current) block.number > stored is false and settle will also revert.
        // Instead we check whether calling settle in the next block succeeds: advance one block and see
        // if settle can succeed (returns/does not revert) — in the reference, after advancing one block,
        // the stored block (current_at_lock+1) is < block.number so settle may proceed; in the mutant
        // stored==current_at_lock so after advancing one block settle may also proceed. That would be
        // ambiguous. Therefore we instead assert the decisive universal property: after lockInGuess
        // completes, the stored guesses[caller].block is not equal to block.number (the reference sets +1,
        // so stored != current; the mutant sets equal for some inputs). We obtain stored block by
        // calling a small view helper via try/catch on settle to provoke a revert containing no data
        // if requirement fails — but since we may only observe public surface, we use a two-step observed
        // technique: perform a low-level staticcall to read the mapping via the ABI of the auto-generated
        // getter. The mapping is named `guesses` in the contract source; its getter signature is
        // guesses(address) returns (uint256,uint256) or rather returns (uint256,bytes32) depending on order.
        // However we cannot rely on that from here; instead call a small external view by performing
        // staticcall to the auto-generated getter selector computed for guesses(address).

        // Compute selector for guesses(address) -> returns (uint256,bytes32) in same order as struct
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("guesses(address)")), caller);
        (bool ok, bytes memory ret) = address(c).staticcall(data);
        // Ensure the call succeeded (getter exists)
        require(ok, "getter call failed");
        // Decode: struct is (uint256 block, bytes32 guess) per source
        (uint256 storedBlock, bytes32 storedGuess) = abi.decode(ret, (uint256, bytes32));

        // The universal property we assert: storedBlock != block.number
        // For the correct contract this always holds because it stored block.number + 1.
        // The mutant that stores block.number will make storedBlock == block.number for some inputs,
        // so this assertion will fail on the mutant for those inputs.
        assertTrue(storedBlock != block.number);
    }
}

