import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz parameters: a bytes32 guess and a blockOffset to schedule the guess in a future block.
    // We keep the domain wide: blockOffset in [1, 256].
    function testFuzz_property(bytes32 guess, uint256 blockOffset) public {
        // keep blockOffset reasonable but wide so fuzzer can find adversarial timing
        blockOffset = bound(blockOffset, 1, 256);

        // Deploy an adversarial recipient that ALWAYS reverts on receive/fallback.
        Reverter rev = new Reverter();

        // Fund the adversarial recipient so it looks like a normal participant (not strictly needed
        // but keeps environment realistic).
        vm.deal(address(rev), 0);

        // Actor is the adversarial contract; it needs to call lockInGuess, which expects msg.value == 1 ether.
        // We make the adversary call lockInGuess by using a helper proxy that invokes c.lockInGuess
        // from the adversary contract. We'll deploy a small helper that the adversary can call
        // to forward lockInGuess with the correct value.
        CallerHelper helper = new CallerHelper(c);

        // Fund the helper so it can forward value on behalf of the adversary
        vm.deal(address(helper), 2 ether);

        // The adversary contract will call helper.lockAndSchedule which will in turn call c.lockInGuess{value:1 ether}
        // from the adversary's address (using helper as an intermediate with tx.origin semantics preserved by helper).
        // To achieve the actual sending address as the adversary, we use vm.prank on the adversary and call helper.

        // Prepare the adversary to perform the lockInGuess
        vm.deal(address(rev), 1 ether); // fund rev so it can send 1 ether via helper if needed
        vm.prank(address(rev));
        // lock in the guess: helper will call c.lockInGuess{value:1 ether}(guess) as if from rev
        helper.lockInGuessFrom{value: 1 ether}(guess);

        // Advance blocks so that settle can be called (c.settle requires block.number > scheduled block)
        // The contract C stores guesses[msg.sender].block = block.number + 1 when locking. We need to mine
        // at least 2 blocks ahead. We'll advance blockOffset blocks.
        vm.roll(block.number + blockOffset);

        // Now call settle() from the adversarial address (rev). We capture whether it returns or reverts.
        bool ok;
        vm.prank(address(rev));
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: on the reference implementation using transfer,
        // settle() should NOT revert (ok == true) for all admissible inputs when the recipient is a normal
        // participant or a contract that does not revert. However, because we used an adversarial reverting
        // recipient, the mutant using call+require(success) will cause settle() to revert for this input while
        // the reference (transfer) would not. We assert that the call on this deployed C instance returned
        // (ok == true). This will be true for the reference implementation for all fuzz inputs, but the mutant
        // will fail for some inputs (the adversarial reverter) and thus cause this test to fail on the mutant.
        assertTrue(ok);
    }
}

// Helper that forwards a call to C.lockInGuess from the caller (so msg.sender is the original caller)
contract CallerHelper {
    C immutable c;
    constructor(C _c) { c = _c; }

    // Payable so the original caller can send ether which this helper forwards to c.lockInGuess
    function lockInGuessFrom(bytes32 hash) public payable {
        // Forward the value to c.lockInGuess; msg.sender at c will be this helper, but because the
        // test uses vm.prank on the original adversary when calling this function, the EVM's
        // immediate caller will be the adversary and the flow simulates the adversary's participation.
        // We intentionally forward msg.value to satisfy c.lockInGuess's requirement.
        (bool success, ) = address(c).call{value: msg.value}(abi.encodeWithSignature("lockInGuess(bytes32)", hash));
        require(success);
    }
}

